// Money gate (docs/31, F-SYS-051, docs/24 s7.1): the web's money formatters against the shared corpus
// contract/fixtures/money-format-corpus.json (generated by tools/ci/money-format-corpus.py from an integer-only oracle).
// backend/sync MoneyFormatCorpusTest reads the same file for shared:rules Formats/Money, so phone, server and web must
// show the same figure for the same milli-taka.
//
// KNOWN lists the formatter/format pairs that disagree with the corpus today (findings routed to the owning lane). It may
// only shrink (KNOWN_CEILING is its exact size): a pair listed here must still disagree, on no more amounts than
// recorded (so a fix fails this test until its line is deleted), and a pair not listed must agree on all 200 amounts.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { formatMtk, formatMtkExact } from "@/lib/admin/money";
import { formatPriceMtk, mtkToTaka as priceMtkToTaka, parseTakaToMtk } from "@/lib/admin/price-money";
import { takaToMtk } from "@/lib/admin/taka";
import { formatLakhCrore, mtkToTaka as lakhMtkToTaka } from "@/lib/dash/lakh";
import { formatTaka, formatTakaDisplay, mtkToTaka as reportMtkToTaka } from "@/lib/reports/format";
import type { Locale } from "@/lib/i18n";

type ByLocale = { en: string; bn: string };
interface Entry {
  mtk: number;
  note: string;
  expect: { money2: ByLocale; amount2: ByLocale; money3: ByLocale; plain3: string; lakh_crore: ByLocale };
}
interface Corpus {
  taka_sign: string;
  lakh_crore_words: Record<Locale, { lakh: string; crore: string }>;
  amounts: Entry[];
}

const corpus = JSON.parse(readFileSync(resolve(__dirname, "../../contract/fixtures/money-format-corpus.json"), "utf8")) as Corpus;
const LOCALES: Locale[] = ["en", "bn"];
const BN = "০১২৩৪৫৬৭৮৯";
const bnDigits = (s: string) => s.replace(/\d/g, (d) => BN[Number(d)] ?? d);

/** formatter id -> (entry, locale) -> [actual, expected]. */
const CHECKS: Record<string, (e: Entry, l: Locale) => [string, string]> = {
  // Hero/stat card: formatTakaDisplay plus the " ৳" the Money component appends (components/kit/hero-card.tsx).
  "reports/format.formatTakaDisplay+sign:money2": (e, l) => [`${formatTakaDisplay(l, e.mtk)} ${corpus.taka_sign}`, e.expect.money2[l]],
  "reports/format.formatTakaDisplay:amount2": (e, l) => [formatTakaDisplay(l, e.mtk), e.expect.amount2[l]],
  "admin/money.formatMtk:amount2": (e, l) => [formatMtk(l, e.mtk), e.expect.amount2[l]],
  "reports/format.formatTaka:money3": (e, l) => [formatTaka(l, e.mtk), e.expect.money3[l]],
  "admin/money.formatMtkExact:money3": (e, l) => [formatMtkExact(l, e.mtk), e.expect.money3[l]],
  "reports/format.mtkToTaka:plain3": (e) => [reportMtkToTaka(e.mtk), e.expect.plain3],
  "admin/price-money.mtkToTaka:plain3": (e) => [priceMtkToTaka(e.mtk), e.expect.plain3],
  "admin/price-money.formatPriceMtk:plain3": (e, l) => [formatPriceMtk(l, e.mtk), l === "bn" ? bnDigits(e.expect.plain3) : e.expect.plain3],
  "dash/lakh.formatLakhCrore:lakh_crore": (e, l) => [formatLakhCrore(l, lakhMtkToTaka(e.mtk), corpus.lakh_crore_words[l]), e.expect.lakh_crore[l]],
};

/**
 * Findings (2026-10-18, qa money gate). Each names the locale(s) that disagree and why; delete the line when fixed.
 * - Intl "bn-BD" groups the South Asian way (১২,৩৪,৫৬৭.০০) while F-SYS-051 and shared:rules Formats use Western
 *   3-digit grouping in both locales (১,২৩৪,৫৬৭.০০): every bn amount from 1 lakh taka up differs between the web and
 *   the phone.
 */
const KNOWN: Record<string, Partial<Record<Locale, number>>> = {
  // formatter/format -> locale -> the most corpus amounts that may differ (measured 2026-10-18; may only go down)
  "reports/format.formatTakaDisplay+sign:money2": { bn: 95 },
  "reports/format.formatTakaDisplay:amount2": { bn: 95 },
  "admin/money.formatMtk:amount2": { bn: 95 },
  "reports/format.formatTaka:money3": { bn: 95 },
  "admin/money.formatMtkExact:money3": { bn: 95 },
  "dash/lakh.formatLakhCrore:lakh_crore": { bn: 3 },
};
/** The exact number of known (formatter, locale) pairs, like CEILING in tools/ci/money-float-scan.py: lower it with each fix. */
const KNOWN_CEILING = 6;

/** Mismatches of [id]; with [ignoreGrouping] the separators are dropped first (a known grouping finding hides nothing else). */
function mismatches(id: string, locale: Locale, ignoreGrouping = false): string[] {
  const out: string[] = [];
  const norm = (s: string) => (ignoreGrouping ? s.replace(/,/g, "") : s);
  for (const e of corpus.amounts) {
    const [actual, want] = CHECKS[id]!(e, locale);
    if (norm(actual) !== norm(want)) out.push(`${e.mtk} (${e.note}): got "${actual}", corpus "${want}"`);
  }
  return out;
}

describe("money format corpus (contract/fixtures/money-format-corpus.json)", () => {
  it("holds 200 integer milli-taka amounts within the safe integer range", () => {
    expect(corpus.amounts).toHaveLength(200);
    for (const e of corpus.amounts) expect(Number.isSafeInteger(e.mtk)).toBe(true);
  });

  for (const id of Object.keys(CHECKS)) {
    for (const locale of LOCALES) {
      const limit = KNOWN[id]?.[locale];
      const known = limit !== undefined;
      it(`${id} [${locale}] ${known ? "still disagrees (known finding)" : "matches every amount"}`, () => {
        const bad = mismatches(id, locale);
        if (known) {
          // A fixed finding must leave KNOWN (the list only shrinks).
          console.info(`known finding ${id} [${locale}]: ${bad.length}/${corpus.amounts.length} differ, e.g. ${bad[bad.length - 1]}`);
          expect(bad.length, `${id} [${locale}] now matches: delete it from KNOWN and lower KNOWN_CEILING`).toBeGreaterThan(0);
          expect(bad.length, `${id} [${locale}]: more amounts differ than recorded`).toBeLessThanOrEqual(limit);
          // The known finding is grouping only: digits, decimals, rounding and sign still match on every amount.
          expect(mismatches(id, locale, true).slice(0, 10)).toEqual([]);
        } else {
          expect(bad.slice(0, 10), `${bad.length} of ${corpus.amounts.length} differ`).toEqual([]);
        }
      });
    }
  }

  it("KNOWN names only formatters that exist (no stale entries) and holds exactly KNOWN_CEILING pairs", () => {
    for (const id of Object.keys(KNOWN)) expect(Object.keys(CHECKS)).toContain(id);
    expect(Object.values(KNOWN).reduce((n, byLocale) => n + Object.keys(byLocale).length, 0)).toBe(KNOWN_CEILING);
  });

  it("parsing the shown amount gives back the same milli-taka (no float on the way in)", () => {
    for (const e of corpus.amounts) {
      const plain = e.expect.plain3;
      const wholeDigits = plain.replace(/^-/, "").split(".")[0]!.length;
      if (wholeDigits > 12) continue; // the editors accept at most 12 whole-taka digits
      expect(takaToMtk(e.expect.money3.en), `takaToMtk(${e.expect.money3.en})`).toBe(e.mtk);
      expect(takaToMtk(e.expect.money3.bn), `takaToMtk(${e.expect.money3.bn})`).toBe(e.mtk);
      if (e.mtk >= 0) expect(parseTakaToMtk(plain), `parseTakaToMtk(${plain})`).toBe(e.mtk);
    }
  });
});
